import json, math

def by_variant(samples):
    d={}
    for s in samples: d.setdefault(s['variant'],[]).append(s)
    return d

def local_majority(lst):
    counts={}
    for s in lst: counts[s['answer']]=counts.get(s['answer'],0)+1
    return max(counts.items(), key=lambda x:x[1])[0]

def majority_of_variant_majorities(samples, k):
    d = by_variant(samples)
    picks=[]
    for v, lst in d.items():
        sub = lst[:k]
        if sub: picks.append(local_majority(sub))
    counts={}
    for a in picks: counts[a]=counts.get(a,0)+1
    return max(counts.items(), key=lambda x:x[1])[0]

for f in ['alg_deep.json','geo_deep.json','comb_deep.json','nt_deep.json']:
    qs = json.load(open(f))['questions']
    n=len(qs)
    print('===',f)
    for k in [2,3,4,6]:
        acc=0
        for q in qs:
            if majority_of_variant_majorities(q['samples'], k)==q['correct_answer']: acc+=1
        print(f'  k={k} (total~{5*k}) acc={acc/n:.3f}')
